'use strict';
// A self-contained, in-memory product simulation. No personal data is sent or saved.
let lang='en',page='home',step=0,status='draft',request=null,storyStage=0,appTimer;
const steps=['recipient','address','service','provider','permissions','review','status'];
const form={who:'family',relation:'mother',country:'us',area:'lotus',service:'home',provider:1,day:1,slot:0,agreement:false,updates:true,ack:false};
const doctors=[{id:1,en:'Dr. Salma Hassan',ar:'د. سلمى حسن',initials:'SH',spec:['General practice','طب عام'],fee:900},{id:2,en:'Dr. Karim Nabil',ar:'د. كريم نبيل',initials:'KN',spec:['Internal medicine','باطنة'],fee:1100}];
const $=s=>document.querySelector(s), T=(en,ar)=>lang==='ar'?ar:en;
const icons={home:'<path d="m3 11 9-8 9 8M5 10v11h14V10M9 21v-7h6v7"/>',family:'<circle cx="8" cy="7" r="3"/><circle cx="17" cy="8" r="2.5"/><path d="M2 21v-4a6 6 0 0 1 12 0v4m2-7a5 5 0 0 1 6 5v2"/>',person:'<circle cx="12" cy="7" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/>',pin:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="3"/>',video:'<rect x="3" y="5" width="13" height="14" rx="4"/><path d="m16 10 5-3v10l-5-3"/>',shield:'<path d="m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6Z"/><path d="m8 12 3 3 5-6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',heart:'<path d="M20 5c-3-3-7-1-8 2-1-3-5-5-8-2-5 5 8 15 8 15S25 10 20 5Z"/>',vet:'<ellipse cx="12" cy="16" rx="5" ry="4"/><ellipse cx="5" cy="9" rx="2" ry="3"/><ellipse cx="10" cy="5" rx="2" ry="3"/><ellipse cx="16" cy="6" rx="2" ry="3"/><ellipse cx="20" cy="11" rx="2" ry="3"/>',nurse:'<rect x="4" y="6" width="16" height="15" rx="4"/><path d="M9 6V3h6v3m-3 5v6m-3-3h6"/>',lab:'<path d="M9 2h6m-5 0v7L4 19q-1 3 3 3h10q4 0 3-3L14 9V2M7 15h10"/>',pharmacy:'<path d="M9 3h6v6h6v6h-6v6H9v-6H3V9h6Z"/>',check:'<path d="m5 12 5 5L20 6"/>',help:'<path d="M4 13v-2a8 8 0 0 1 16 0v2M4 12h3v7H4q-2 0-2-3t2-4Zm16 0h-3v7h3q2 0 2-3t-2-4Zm-2 7q0 3-6 3"/>',globe:'<circle cx="12" cy="12" r="10"/><ellipse cx="12" cy="12" rx="4" ry="10"/><path d="M2 12h20"/>',card:'<rect x="2" y="5" width="20" height="14" rx="3"/><path d="M2 10h20m-16 5h4"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',calendar:'<rect x="3" y="5" width="18" height="17" rx="3"/><path d="M7 2v6m10-6v6M3 11h18m-12 5 2 2 4-4"/>',briefcase:'<rect x="3" y="7" width="18" height="14" rx="3"/><path d="M8 7V3h8v4M3 13q9 5 18 0"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>'};
function icon(k){return `<span class="icon" aria-hidden="true"><svg viewBox="0 0 24 24">${icons[k]||icons.heart}</svg></span>`;}
function button(text,attrs='',cls='primary'){return `<button class="${cls}" ${attrs}>${text}</button>`;}
function link(text,route){return `<a href="#${route}">${text}</a>`;}
function money(v){return `${v.toLocaleString(lang==='ar'?'ar-EG':'en-GB')} ${T('EGP','جنيه')}`;}
function serviceName(){return form.service==='video'?T('Video consultation','استشارة فيديو'):T('Adult home-doctor visit','زيارة دكتور منزلية للكبار');}
function recipient(){if(form.who==='self')return T('You · demo adult','إنت · شخص بالغ للتجربة');return ({mother:T('Mona · mother (example)','منى · الوالدة (مثال)'),father:T('Hassan · father (example)','حسن · الوالد (مثال)'),relative:T('Nour · adult relative (example)','نور · قريب بالغ (مثال)')})[form.relation];}
function address(){return form.area==='outside'?T('Outside the example area','برّه نطاق المثال'):form.area==='lotus'?T('North Lotus, Fifth Settlement','اللوتس الشمالية، التجمع الخامس'):T('Fifth Settlement boundary — to check','حدود التجمع الخامس — محتاجة مراجعة');}
function provider(){return doctors.find(d=>d.id===form.provider)||doctors[0];}
function cost(){return form.service==='video'?300:provider().fee;}
function serviceDate(){const now=new Date();const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Africa/Cairo',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(now);const n=k=>Number(parts.find(x=>x.type===k).value);const target=Date.UTC(n('year'),n('month')-1,n('day')+form.day,form.slot===0?13:16);let utc=target;for(let i=0;i<3;i++){const p=new Intl.DateTimeFormat('en-GB',{timeZone:'Africa/Cairo',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).formatToParts(new Date(utc));const v=k=>Number(p.find(x=>x.type===k).value);utc+=target-Date.UTC(v('year'),v('month')-1,v('day'),v('hour'),v('minute'),v('second'));}return new Date(utc);}
function dateISO(offset){const p=new Intl.DateTimeFormat('en-CA',{timeZone:'Africa/Cairo',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());const n=k=>Number(p.find(x=>x.type===k).value);return new Date(Date.UTC(n('year'),n('month')-1,n('day')+offset)).toISOString().slice(0,10);}
function availableDays(){return Array.from({length:10},(_,i)=>i+1).filter(i=>![5,6].includes(new Date(dateISO(i)+'T12:00:00Z').getUTCDay())).slice(0,3);}
function timeLabel(zone='Africa/Cairo'){return new Intl.DateTimeFormat(lang==='ar'?'ar-EG':'en-GB',{timeZone:zone,weekday:'short',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit',hour12:true}).format(serviceDate());}
function windowLabel(){return form.service==='video'?T(form.slot===0?'13:00 Egypt time':'16:00 Egypt time',form.slot===0?'١ ظهرًا بتوقيت مصر':'٤ عصرًا بتوقيت مصر'):T(form.slot===0?'13:00–14:00 arrival window':'16:00–17:00 arrival window',form.slot===0?'الوصول من ١ لـ٢ ظهرًا':'الوصول من ٤ لـ٥ عصرًا');}
function head(){return `<div class="notice">${T('Interactive concept · Not a live service · Use fictional details only','تجربة تفاعلية · مش خدمة شغّالة · استخدم بيانات المثال بس')}</div><header class="header"><div class="header-inner"><a class="brand" href="#home" aria-label="CasaDoctors home"><img src="${window.HOME_BRAND}" alt=""><span>CasaDoctors</span></a><nav class="nav" aria-label="${T('Primary navigation','القائمة الرئيسية')}">${link(T('Home visits','زيارات منزلية'),'home-visits')}${link(T('Video care','استشارة فيديو'),'video')}${link(T('How it works','إزاي بتشتغل'),'how')}${link(T('For providers','لمقدمي الخدمة'),'providers')}${link(T('Help','المساعدة'),'help')}</nav><div class="actions">${button(T('Get the app','نزّل التطبيق'),'data-modal="app"','dark app-button')}${button(T('العربية','English'),'data-lang','lang')}</div></div></header>`;}
function bottom(){const nav=[['home','home',T('Home','الرئيسية')],['book/recipient','calendar',T('Arrange care','رتّب رعاية')],['care','heart',T('My care','رعايتي')],['help','help',T('Help','المساعدة')]];return `<nav class="mobile-nav" aria-label="${T('Mobile navigation','قائمة الموبايل')}">${nav.map(([route,i,n])=>`<a href="#${route}" class="${page===(route.startsWith('book')?'book':route)?'active':''}" ${page===(route.startsWith('book')?'book':route)?'aria-current="page"':''}>${icon(i)}${n}</a>`).join('')}</nav>`;}
function footer(){return `<footer class="footer"><div class="wrap"><div class="footer-top"><a class="brand" href="#home">CasaDoctors</a><div class="footer-links">${link(T('Home visits','زيارات منزلية'),'home-visits')}${link(T('For providers','لمقدمي الخدمة'),'providers')}${link(T('Help & privacy','المساعدة والخصوصية'),'help')}<a href="./#s29">${T('Back to the plan','ارجع للخطة')}</a><a href="#app" data-modal="app">${T('Get the app','نزّل التطبيق')}</a></div></div><small>${T('Home-first website concept · Vireal · All providers, prices, availability, coverage and transactions are fictional. International access and payment are not verified. No personal or medical information is collected. Campaign photography is AI-generated; people shown are fictional.','تصوّر لموقع كازا دكتورز · Vireal · الدكاترة والأسعار والمواعيد والنطاق والدفع أمثلة للتجربة. الحجز والدفع من برّه مصر لسه محتاجين اختبار. مفيش جمع لبيانات شخصية أو طبية. صور الحملة مولّدة بالذكاء الاصطناعي والأشخاص فيها مش حقيقيين.')}</small></div></footer>`;}
function home(){return `<main id="main"><div class="wrap"><section class="hero"><div class="hero-copy"><span class="eyebrow">${T('At home. With the people who matter.','في البيت. وسط الناس اللي يهمّوك.')}</span><h1>${T('Care that<br><em>comes to you.</em>','الرعاية تيجي<br><em>لحد عندك.</em>')}</h1><p>${T('For you. For a parent. Even when you’re far away. Arrange a suitable home visit around the person who needs it, and the address that matters.','ليك أو لحد من أهلك، حتى لو إنت بعيد. رتّب زيارة منزلية مناسبة، على عنوان اللي محتاج الرعاية وفي معاد يناسبه.')}</p><div class="hero-actions">${button(T('Try the family booking flow','جرّب تحجز لحد من أهلك'),'data-start="family"')}${button(T('I’m booking for myself','بحجز لنفسي'),'data-start="self"','')}</div><small>${T('Explore the proposed experience. Home-service launch is still being prepared.','شوف التجربة المقترحة. خدمة الزيارات المنزلية لسه في مرحلة التجهيز.')}</small></div><div><div class="hero-photo"><img src="assets/launch-review/caregiver-scene.svg" alt="${T('Illustrative home visit: an older woman talking with a healthcare professional in her living room','تصوّر لزيارة منزلية: سيدة بتتكلم مع مقدّمة رعاية في بيتها')}" fetchpriority="high"><span class="photo-tag">${T('A little less to coordinate.','ترتيبات أقل. واهتمام في مكانه.')}</span><div class="float-card float-one">${icon('globe')}<b>${T('You’re in New York.','إنت في نيويورك.')}</b>${T('Arranging care for your mother.','وبترتّب رعاية لمامتك.')}</div><div class="float-card float-two">${icon('home')}<b>${T('She’s at home in Egypt.','وهي في بيتها في مصر.')}</b><span class="pulse-dot"></span>${T('Her address comes first.','البداية من عنوانها.')}</div></div><div class="caption">${T('Illustrative campaign scene · fictional people','تصوّر للحملة · أشخاص غير حقيقيين')}</div></div></section><div class="trust-row"><div>${icon('pin')}<span>${T('Start with the recipient’s address','ابدأ بعنوان اللي هيستقبل الزيارة')}</span></div><div>${icon('shield')}<span>${T('Clear roles. Private care details.','كل واحد ليه دوره. وتفاصيل الرعاية ليها خصوصيتها.')}</span></div><div>${icon('check')}<span>${T('Know when a request is confirmed','اعرف إمتى طلبك اتأكد فعلًا')}</span></div></div><section class="section" id="family-story"><div class="story reveal"><div><span class="eyebrow">${T('Different places. One thoughtful plan.','أماكن مختلفة. وترتيب يلمّ التفاصيل.')}</span><h2>${T('You don’t have to be nearby<br>to help arrange her care.','مش لازم تكون جنبها<br>علشان ترتّب لها رعاية.')}</h2><p>${T('Who’s booking? Who will receive the visit? Where should the professional go? Three different details, brought together without confusing payment with permission.','مين بيحجز؟ مين هيستقبل الزيارة؟ والدكتور هيروح على أنهي عنوان؟ بنرتّب التفاصيل مع بعض، من غير ما الدفع يبقى معناه إن كل التفاصيل الطبية متاحة للي دفع.')}</p><div class="story-chips"><span class="pill">${T('Booker / payer','اللي بيحجز ويدفع')}</span><span class="pill">${T('Recipient','اللي هيستقبل الرعاية')}</span><span class="pill">${T('Service address','عنوان الزيارة')}</span></div></div><div id="storyScene" class="story-visual">${scenario()}</div></div></section><section class="section" id="services"><div class="section-head"><div><span class="eyebrow">${T('One clear starting point','بداية واضحة')}</span><h2>${T('Home first.<br>More, when it’s ready.','البيت هو البداية.<br>والباقي لما يكون جاهز.')}</h2></div><p>${T('We’re preparing scheduled, non-emergency adult home-doctor visits in one proposed Fifth Settlement area. Each additional service needs its own team, coverage and checks.','بنجهّز زيارات دكتور منزلية للكبار، للحالات غير الطارئة، في نطاق مقترح بالتجمع الخامس. كل خدمة جديدة ليها فريق ونطاق وتجهيزات لازم تكتمل الأول.')}</p></div><div class="service-grid">${serviceCard('home',T('Doctor at home','دكتور في البيت'),T('First pilot · in preparation','أول تجربة تشغيل · بنجهّزها'),T('A suitable adult consultation, at the supported address.','كشف مناسب للكبار، على عنوان داخل نطاق الخدمة.'),'home-visits',true)}${serviceCard('video',T('Video consultation','استشارة فيديو'),T('Second priority · subject to readiness','الخطوة التانية · حسب الجاهزية'),T('For cases a professional can appropriately assess remotely.','للحالات اللي المختص شايف إن الفيديو مناسب ليها.'),'video')}${serviceCard('vet',T('Veterinary home care','بيطري في البيت'),T('Future service','خدمة لاحقة'),T('A separate home-care journey for your pet.','تجربة منفصلة لرعاية حيوانك الأليف في البيت.'),'vet')}${serviceCard('nurse',T('Nursing at home','تمريض منزلي'),T('Future service','خدمة لاحقة'),T('Specific tasks, with the right professional oversight.','مهام محددة، بإشراف مهني مناسب.'),'nurse')}${serviceCard('lab',T('Home diagnostics','تحاليل في البيت'),T('Partner-dependent','مرتبطة بتجهيز الشركاء'),T('Clear preparation, collection and private results.','تعليمات واضحة للسحب واستلام النتيجة بخصوصية.'),'lab')}${serviceCard('pharmacy',T('Pharmacy delivery','توصيل من الصيدلية'),T('Partner-dependent','مرتبطة بتجهيز الشركاء'),T('A participating pharmacy, with stock and order review.','صيدلية مشاركة، ومراجعة لتوفّر المنتجات وتفاصيل الطلب.'),'pharmacy')}</div></section><section class="section" id="how-it-works"><div class="section-head"><div><span class="eyebrow">${T('Fewer loose ends','كل تفصيلة في مكانها')}</span><h2>${T('A visit takes more<br>than choosing a time.','الزيارة مش بس<br>اختيار معاد.')}</h2></div>${button(T('Walk through the booking','جرّب خطوات الحجز'),'data-start="family"','')}</div><div class="steps">${[[T('The person and the place','الشخص والعنوان'),T('Choose yourself or someone else, then the recipient’s service address.','اختار لنفسك أو لحد تاني، وبعدها عنوان اللي هيستقبل الرعاية.')],[T('A suitable visit','زيارة مناسبة'),T('Review the service, example professional, full fee and arrival window.','راجع الخدمة والدكتور والسعر كامل وفترة الوصول.')],[T('A clear confirmation','تأكيد واضح'),T('Follow provider acceptance and payment status before treating the visit as confirmed.','تابع قبول الدكتور وحالة الدفع قبل ما تعتبر الزيارة مؤكدة.')],[T('Help through the visit','مساعدة لحد ما الزيارة تخلص'),T('Preparation, permitted updates, changes and payment support stay together.','تعليمات التجهيز والتحديثات المسموح بيها والتغييرات ومساعدة الدفع في مكان واحد.')]].map((x,i)=>`<article class="step-card reveal"><span>0${i+1}</span><h3>${x[0]}</h3><p>${x[1]}</p></article>`).join('')}</div></section><section class="section"><div class="wide-cta reveal"><div><span class="eyebrow">${T('For the professionals who make it possible','لمقدمي الخدمة اللي بيخلّوا ده ممكن')}</span><h2>${T('Your time. Your area.<br>A visit you can commit to.','وقتك. منطقتك.<br>وزيارة تقدر تلتزم بيها.')}</h2><p>${T('Make suitable services available around your actual working hours and travel time. Explore the proposed CasaBusiness partnership.','حدّد الخدمات اللي بتقدمها، والمنطقة اللي تقدر تزورها، والمواعيد المناسبة ليك مع وقت المشوار. اعرف شكل الشراكة المقترحة من خلال CasaBusiness.')}</p>${button(T('Explore the partnership','اعرف تفاصيل الشراكة'),'data-go="providers"','')}</div><div><div class="mini-journey">${icon('briefcase')}${icon('pin')}${icon('clock')}</div><p>${T('Professional scope → service area → usable windows → reviewed requests. No guaranteed volume or earnings.','نطاق مهني → منطقة خدمة → مواعيد فعلية → طلبات تراجعها. من غير وعود بعدد طلبات أو دخل مضمون.')}</p></div></div></section><section class="section faq"><div><span class="eyebrow">${T('Before you begin','قبل ما تبدأ')}</span><h2>${T('The questions<br>that matter.','الأسئلة<br>اللي تهمّك.')}</h2></div><div>${faqs()}</div></section></div></main>`;}

function scenario(){const states=[
[['globe',T('Omar · the son','عمر · الابن'),T('New York · arranges and pays','نيويورك · بيرتّب ويدفع')],['person',T('Mona · his mother','منى · والدته'),T('Egypt · chooses to receive care','مصر · بتوافق تستقبل الرعاية')],T('Different people. Different permissions.','أشخاص مختلفين. وصلاحيات مختلفة.')],
[['globe',T('Booker’s location','مكان اللي بيحجز'),T('Not the matching address','مش عنوان البحث عن الخدمة')],['home',T('Recipient’s home','بيت اللي هيستقبل الرعاية'),T('North Lotus · example catchment','اللوتس الشمالية · نطاق تجريبي')],T('Find the service where she needs it.','دور على الخدمة في المكان اللي هي محتاجاها فيه.')],
[['clock',T('Your time view','التوقيت عندك'),T('New York · shown for planning','نيويورك · علشان ترتّب')],['calendar',T('Her visit window','فترة زيارتها'),T('Egypt time · service reference','بتوقيت مصر · مرجع الخدمة')],T('One visit. Two useful time displays.','زيارة واحدة. والتوقيت واضح لكل واحد.')],
[['briefcase',T('Professional acceptance','قبول المختص'),T('A request needs review','الطلب محتاج مراجعة')],['check',T('Payment + confirmation','الدفع والتأكيد'),T('Only after the required steps','بعد اكتمال الخطوات المطلوبة')],T('Know what’s pending, and what’s confirmed.','تعرف إيه لسه معلّق، وإيه اتأكد.')]
];const st=states[storyStage];return '<div class="story-tabs" role="group" aria-label="'+T('Explore the family story','اكتشف خطوات ترتيب الرعاية')+'">'+[T('Who','مين'),T('Where','فين'),T('When','إمتى'),T('Confirmed','التأكيد')].map((v,i)=>'<button data-story="'+i+'" aria-pressed="'+(storyStage===i)+'">'+v+'</button>').join('')+'</div><svg class="story-line" viewBox="0 0 450 310" preserveAspectRatio="none" aria-hidden="true"><path d="M100 85C390 90 50 235 350 240"/></svg>'+st.slice(0,2).map(n=>'<div class="story-node page-enter">'+icon(n[0])+'<div><b>'+n[1]+'</b><small>'+n[2]+'</small></div></div>').join('')+'<p class="story-explanation" aria-live="polite">'+st[2]+'</p>';}

function serviceCard(i,title,badge,desc,route,featured=false){return `<article class="service ${featured?'featured':''} reveal">${icon(i)}<span class="badge">${badge}</span><h3>${title}</h3><p>${desc}</p>${button(T('Explore','اعرف أكتر'),`data-go="${route}"`,featured?'':'text-btn')}</article>`;}
function faqs(){return [[T('Can I arrange a visit for a parent?','ينفع أرتّب زيارة لوالدتي أو والدي؟'),T('That is a core design goal. The recipient’s agreement or appropriate representative authority is needed. You can preview the flow with fictional details; this is not a live booking.','دي من أهم الحالات اللي بنصمّم علشانها. لازم موافقة اللي هيستقبل الخدمة أو تفويض مناسب. تقدر تجرّب الخطوات ببيانات المثال، بس ده مش حجز فعلي.')],[T('Is the service available now?','الخدمة شغّالة دلوقتي؟'),T('This is a prelaunch concept. The proposed first pilot is scheduled adult home-doctor care in a bounded North Lotus / Fifth Settlement area. Real coverage, slots and fees still need acceptance.','ده تصوّر قبل التشغيل. البداية المقترحة زيارات دكتور منزلية للكبار في نطاق محدد باللوتس الشمالية والتجمع الخامس. النطاق والمواعيد والأسعار الفعلية لسه محتاجة اعتماد.')],[T('Can I book and pay from abroad?','ينفع أحجز وأدفع وأنا برّه مصر؟'),T('The flow demonstrates that situation. International phone access and cards must pass testing before it is offered. The service recipient remains in the accepted Egypt area.','التجربة بتوضح الحالة دي. أرقام التليفون ووسائل الدفع من برّه مصر لازم تتختبر قبل ما نوعد بإتاحتها. الخدمة نفسها بتتقدّم للمستفيد داخل النطاق المعتمد في مصر.')],[T('Does paying give me access to medical details?','لو أنا اللي دفعت، هشوف التفاصيل الطبية؟'),T('No. Booking and payment updates are separate from clinical records. Sharing care details requires the appropriate permission and private process.','لأ. تحديثات الحجز والدفع منفصلة عن الملف الطبي. مشاركة تفاصيل الرعاية ليها موافقة مناسبة وطريقة خاصة وآمنة.')],[T('Is this for emergencies?','ينفع للحالات الطارئة؟'),T('No. Home visits and video here are scheduled, non-emergency services. Seek local emergency care for an emergency; do not wait for a booking or a support reply.','لأ. الزيارات والفيديو هنا خدمات بميعاد للحالات غير الطارئة. في الطوارئ، اطلب رعاية طارئة محلية فورًا، ومتستناش حجز أو رد من الدعم.')]].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('');}
function summary(){return `<aside class="panel summary"><h3>${T('Your example visit','ملخّص الزيارة التجريبية')}</h3>${rows()}<div class="privacy-box">${icon('shield')}<span>${T('Fictional details only. No booking, payment or clinical data leaves this prototype.','بيانات المثال بس. مفيش حجز أو دفع أو بيانات طبية بتتبعت من التجربة دي.')}</span></div></aside>`;}
function rows(full=false){return `<div class="row"><span>${T('Recipient','المستفيد')}</span><b>${recipient()}</b></div><div class="row"><span>${T('Service address','عنوان الخدمة')}</span><b>${address()}</b></div><div class="row"><span>${T('Service','الخدمة')}</span><b>${serviceName()}</b></div>${step>=3||full?`<div class="row"><span>${T('Professional','الدكتور')}</span><b>${lang==='ar'?provider().ar:provider().en}</b></div><div class="row"><span>${T('Egypt service time','ميعاد الخدمة بتوقيت مصر')}</span><b>${timeLabel()}<br>${windowLabel()}</b></div>`:''}${form.country==='us'&&(step>=3||full)?`<div class="row"><span>${T('New York · booker view','نيويورك · توقيت اللي بيحجز')}</span><b>${timeLabel('America/New_York')}</b></div>`:''}<div class="row total"><span>${T('Illustrative total','الإجمالي التجريبي')}</span><b>${money(cost())}</b></div>`;}
function booking(){const titles=[T('Who are you arranging care for?','بترتّب الرعاية لمين؟'),T('Where will the care happen?','الزيارة هتكون على أنهي عنوان؟'),T('What kind of care fits?','أنهي خدمة مناسبة؟'),T('Choose the professional and window.','اختار الدكتور وفترة الزيارة.'),T('Keep everyone’s role clear.','نوضّح دور كل واحد.'),T('Check the details, together.','نراجع التفاصيل مع بعض.'),T('A request is the start.','الطلب هو أول خطوة.')];const subtitles=[T('You can coordinate care without being the person who receives it.','ممكن ترتّب الرعاية من غير ما تكون إنت اللي هتستقبلها.'),T('Use the recipient’s address, even if you are in another city or country.','اختار عنوان اللي هيستقبل الرعاية، حتى لو إنت في مدينة أو بلد تانية.'),T('The home-doctor pilot comes first. Video is a separate, later release.','الزيارات المنزلية هي البداية. الفيديو ليه تجهيز وتشغيل منفصل بعد كده.'),T('These fictional profiles show the information we need before a real launch.','البروفايلات دي أمثلة بتوضّح المعلومات المطلوبة قبل التشغيل الفعلي.'),T('Receiving care, arranging it and paying for it are different responsibilities.','استقبال الرعاية وترتيبها والدفع مسؤوليات مختلفة.'),T('Nothing is charged or booked. You’re about to simulate a request.','مفيش دفع أو حجز فعلي. الخطوة الجاية بتجرّب إرسال الطلب.'),T('Follow acceptance and payment separately. Nothing is sent to a real provider.','تابع قبول الدكتور والدفع كل واحد لوحده. مفيش طلب بيتبعت لدكتور حقيقي.')];return `<main id="main" class="booking-shell page-enter"><div class="booking-head">${button(T('← Back','ارجع →'),'data-back','back')}<span class="eyebrow">${T('Arrange care · Interactive demo','ترتيب رعاية · تجربة تفاعلية')}</span><h1 tabindex="-1" id="pageTitle">${step===6?statusName():titles[step]}</h1><p>${subtitles[step]}</p><div class="progress" aria-label="${T('Booking progress','خطوات الحجز')}">${steps.map((_,i)=>`<span class="${i<=step?'done':''}"></span>`).join('')}</div><div class="step-count"><span>${T('Step','خطوة')} ${step+1} ${T('of','من')} 7</span><span>${T('Example details only','بيانات المثال بس')}</span></div></div>${step>0&&step<5?'<details class="mobile-summary"><summary>'+T('Your selections','اختياراتك لحد دلوقتي')+'</summary>'+rows()+'</details>':''}<div class="booking-layout"><section class="panel">${[recipientStep,addressStep,serviceStep,providerStep,permissionsStep,reviewStep,statusStep][step]()}</section>${summary()}</div></main>${step<6?dock():''}`;}
function choice(value,current,title,desc,i,attr){return `<button class="choice" ${attr}="${value}" aria-pressed="${current===value}">${icon(i)}<b>${title}</b><small>${desc}</small></button>`;}
function recipientStep(){return `<h2>${T('Start with the person.','نبدأ بالشخص.')}</h2><p>${T('The example keeps the person booking separate from the person receiving care.','في المثال بنفرّق بين اللي بيحجز واللي هيستقبل الرعاية.')}</p><div class="choices">${choice('family',form.who,T('Someone I love','حد من أهلي'),T('A parent or another adult relative','والدتي، والدي، أو قريب بالغ'),'family','data-who')}${choice('self',form.who,T('Myself','لنفسي'),T('I’ll receive the care','أنا اللي هستقبل الرعاية'),'person','data-who')}</div>${form.who==='family'?'<label class="field">'+T('Who will receive the visit?','مين هيستقبل الزيارة؟')+'<select id="relation">'+[['mother',T('My mother · Mona','والدتي · منى')],['father',T('My father · Hassan','والدي · حسن')],['relative',T('Another adult relative · Nour','قريب بالغ تاني · نور')]].map(([v,n])=>'<option value="'+v+'" '+(form.relation===v?'selected':'')+'>'+n+'</option>').join('')+'</select></label>':''}<label class="field">${T('Where are you booking from?','بتحجز منين؟')}<select id="country"><option value="us" ${form.country==='us'?'selected':''}>${T('United States · New York example','أمريكا · مثال بتوقيت نيويورك')}</option><option value="eg" ${form.country==='eg'?'selected':''}>${T('Egypt','مصر')}</option></select><small>${T('Only the booker’s time display changes. This does not establish international access or payment support.','ده بيغيّر عرض توقيت اللي بيحجز بس، ومش إثبات إن الحجز والدفع من برّه مصر متاحين.')}</small></label><div class="note">${T('We’ll use fictional names and contacts throughout. Please don’t enter real personal or health information.','هنستخدم أسماء وأرقام تجريبية في كل الخطوات. متدخلش بيانات شخصية أو صحية حقيقية.')}</div>`;}
function addressStep(){return `<h2>${T('The service address comes first.','البداية من عنوان الزيارة.')}</h2><p>${T('We match the visit to the recipient’s location. No GPS permission is needed for this demo.','بنختار الزيارة على أساس مكان اللي هيستقبلها. التجربة مش بتطلب إذن تحديد موقعك.')}</p><label class="field">${T('Recipient’s service area','منطقة اللي هيستقبل الخدمة')}<select id="area"><option value="lotus" ${form.area==='lotus'?'selected':''}>${T('North Lotus · proposed pilot example','اللوتس الشمالية · مثال للنطاق المقترح')}</option><option value="boundary" ${form.area==='boundary'?'selected':''}>${T('Edge of Fifth Settlement · coverage needs checking','طرف التجمع الخامس · النطاق محتاج مراجعة')}</option><option value="outside" ${form.area==='outside'?'selected':''}>${T('Outside the example area','برّه نطاق المثال')}</option></select></label>${form.area!=='lotus'?`<div class="error" role="status"><b>${T('No supported visit shown here.','مفيش زيارة متاحة في المثال هنا.')}</b><p>${T('This address is not accepted in the sample catchment. Choose North Lotus to continue the demo, or explore help. We won’t silently change the recipient’s address.','العنوان ده مش ضمن النطاق المقبول في المثال. اختار اللوتس الشمالية علشان تكمّل التجربة، أو شوف المساعدة. مش هنغيّر عنوان المستفيد من غير موافقته.')}</p>${button(T('Get help','شوف المساعدة'),'data-go="help"','')}</div>`:`<div class="field-grid"><label class="field">${T('Example address','عنوان تجريبي')}<input readonly value="${T('Example building · North Lotus','عمارة تجريبية · اللوتس الشمالية')}"></label><label class="field">${T('Example access note','ملاحظة وصول تجريبية')}<input readonly value="${T('Lift · recipient can answer the door','فيه أسانسير · المستفيد يقدر يفتح الباب')}"></label></div><div class="note">${T('Proposed area, not live coverage. In production, exact address, travel time, access and available visit windows must all be checked privately.','دي منطقة مقترحة، مش نطاق خدمة شغّال. في التطبيق الفعلي لازم نراجع العنوان بالتفصيل ووقت المشوار والدخول والمواعيد بشكل خاص.')}</div>`}`;}
function serviceStep(){return `<h2>${T('A home visit comes first.','الزيارة المنزلية هي البداية.')}</h2><div class="choices">${choice('home',form.service,T('Doctor at home','دكتور في البيت'),T('First proposed pilot · adult, non-emergency','أول تجربة مقترحة · للكبار والحالات غير الطارئة'),'home','data-service')}${choice('video',form.service,T('Video consultation','استشارة فيديو'),T('Preview only · separate readiness gate','تصوّر فقط · تشغيلها محتاج جاهزية منفصلة'),'video','data-service')}</div><div class="note"><b>${T('Suitability comes before availability.','مناسبة الخدمة أهم من وجود معاد.')}</b>${form.service==='home'?T('The proposed visit covers a suitable adult consultation. A qualified professional must review eligibility; this demo does not assess symptoms or provide medical advice.','الزيارة المقترحة لكشف مناسب لشخص بالغ. المختص لازم يراجع مناسبة الحالة؛ التجربة مش بتقيّم أعراض أو بتقدّم نصيحة طبية.'):T('Video is not a default replacement for a home visit. A professional decides suitability. The first recipient location remains within the approved Egypt jurisdiction.','الفيديو مش بديل تلقائي للزيارة المنزلية. المختص هو اللي بيحدّد مناسبته، ومكان المستفيد في أول تشغيل يفضل داخل النطاق المعتمد في مصر.')}</div><p>${T('Not an emergency service. Medicines, tests, nursing and procedures are not included by default.','مش خدمة طوارئ. الأدوية والتحاليل والتمريض والإجراءات مش ضمن الزيارة تلقائيًا.')}</p>`;}
function providerStep(){return `<h2>${T('Know who. Know the details.','اعرف مين هيزورك. وبالتفاصيل.')}</h2><p>${T('All names and professional details below are fictional. Credentials and actual supply must be checked before launch.','كل الأسماء والتفاصيل المهنية هنا أمثلة. المؤهلات والمواعيد الفعلية لازم تتراجع قبل التشغيل.')}</p>${doctors.map(d=>`<article class="provider ${form.provider===d.id?'selected':''}"><div class="provider-top"><div class="avatar" aria-hidden="true">${d.initials}</div><div><h3>${lang==='ar'?d.ar:d.en}</h3><small>${lang==='ar'?d.spec[1]:d.spec[0]} · ${T('Fictional profile','بروفايل تجريبي')}</small></div></div><div class="meta"><span class="pill">${icon(form.service==='home'?'home':'video')}${serviceName()}</span><span class="pill">${money(form.service==='video'?300:d.fee)}</span></div><details><summary>${T('Scope and visit details','نطاق الخدمة وتفاصيل الزيارة')}</summary><p>${T('An eligible adult consultation; professional acceptance is required. Qualification, registration, case suitability and visit content would be verified in the real service. No ratings or verification badge are fabricated here.','كشف مناسب لشخص بالغ، بعد قبول المختص. المؤهلات والتسجيل ومناسبة الحالة وتفاصيل الزيارة لازم تتراجع في الخدمة الفعلية. مفيش تقييمات أو علامة توثيق وهمية في المثال.')}</p></details>${button(form.provider===d.id?T('Selected','تم الاختيار'):T('Choose this example','اختار المثال ده'),`data-provider="${d.id}"`,form.provider===d.id?'dark':'')}</article>`).join('')}<label class="field">${T('Choose a date','اختار يوم')}<input id="visitDate" type="date" value="${dateISO(form.day)}" min="${dateISO(1)}" max="${dateISO(14)}"><small>${T('Open the calendar or use an example day below.','افتح النتيجة أو اختار يوم من أمثلة المواعيد تحت.')}</small></label><div class="slots" role="group" aria-label="${T('Sample available days','أيام متاحة في المثال')}">${availableDays().map(n=>'<button data-day="'+n+'" aria-pressed="'+(form.day===n)+'">'+new Intl.DateTimeFormat(lang==='ar'?'ar-EG':'en-GB',{timeZone:'Africa/Cairo',weekday:'short',day:'numeric',month:'short'}).format(new Date(dateISO(n)+'T12:00:00Z'))+'</button>').join('')}</div>${!availableDays().includes(form.day)?'<div class="error" role="status">'+T('No sample slots on this date. Choose one of the example days to continue.','مفيش مواعيد تجريبية في اليوم ده. اختار يوم من الأمثلة علشان تكمّل.')+'</div>':''}<b>${T('Choose an example window','اختار فترة تجريبية')}</b><div class="slots" role="group" aria-label="${T('Visit windows','فترات الزيارة')}">${[0,1].map(i=>`<button data-slot="${i}" aria-pressed="${form.slot===i}">${form.service==='home'?T(i===0?'13:00–14:00':'16:00–17:00',i===0?'١–٢ ظهرًا':'٤–٥ عصرًا'):T(i===0?'13:00':'16:00',i===0?'١ ظهرًا':'٤ عصرًا')}</button>`).join('')}</div><small>${T('Egypt time · illustrative windows, not approved service hours or a visit-duration promise.','بتوقيت مصر · فترات تجريبية، مش ساعات خدمة معتمدة أو وعد بمدة الكشف.')}</small>${form.country==='us'?`<div class="note">${T('For the booker in New York:','للي بيحجز من نيويورك:')} <b dir="auto">${timeLabel('America/New_York')}</b>${T('Your recipient’s Egypt time remains the service reference. Time-zone conversion follows the selected date.','توقيت المستفيد في مصر هو مرجع الخدمة. فرق التوقيت بيتحسب حسب اليوم اللي اخترته.')}</div>`:''}`;}
function permissionsStep(){return `<h2>${T('A real person, with a choice.','المستفيد ليه اختياره وخصوصيته.')}</h2><p>${T('Use these fictional identities to understand how consent and updates should work. No actual permission is obtained from anyone.','الأسماء دي للتجربة علشان نفهم الموافقة والتحديثات. مش بنحصل على موافقة فعلية من أي شخص.')}</p><div class="field-grid"><label class="field">${T('Booker / payer · example','اللي بيحجز ويدفع · مثال')}<input readonly value="${form.who==='family'?T('Omar · adult son','عمر · الابن البالغ'):T('Demo adult · yourself','شخص بالغ للتجربة · إنت')}"></label><label class="field">${T('Recipient · example','المستفيد · مثال')}<input readonly value="${recipient()}"></label></div><label class="field">${T('Local contact · example, not a real number','التواصل المحلي · مثال مش رقم حقيقي')}<input readonly value="${T('Recipient’s verified contact · not connected','وسيلة تواصل متحقق منها للمستفيد · غير متصلة')}"><small>${T('In production: verify contacts privately and agree who can be contacted if the recipient is unreachable.','في الخدمة الفعلية: التحقق من التواصل بشكل خاص، وتحديد مين نتواصل معاه لو المستفيد مش بيرد.')}</small></label><label class="check"><input type="checkbox" id="agreement" ${form.agreement?'checked':''}><span>${form.who==='family'?T('For this simulation, assume the adult recipient agreed to the visit and the necessary coordination.','في المثال ده، نفترض إن المستفيد البالغ وافق على الزيارة والترتيبات الضرورية.'):T('For this simulation, I choose the example visit for myself.','في المثال ده، أنا باختار الزيارة التجريبية لنفسي.')}<small>${T('A real service must verify consent or appropriate representative authority. Family relationship alone is not permission.','الخدمة الفعلية لازم تتحقق من الموافقة أو تفويض مناسب. القرابة لوحدها مش تصريح.')}</small></span></label>${form.who==='family'?`<label class="check"><input type="checkbox" id="updates" ${form.updates?'checked':''}><span>${T('Example permission: share booking-status updates with Omar.','إذن تجريبي: مشاركة تحديثات حالة الحجز مع عمر.')}<small>${T('Optional. No medical notes, diagnosis, prescription or test results are included.','اختياري. من غير ملاحظات طبية أو تشخيص أو روشتة أو نتائج تحاليل.')}</small></span></label>`:''}<div class="note">${icon('shield')} <b>${T('Paying is not clinical-record access.','الدفع مش تصريح للاطلاع على الملف الطبي.')}</b>${T('Payment receipts go to the payer. Clinical information follows its own authorized, private route.','إيصال الدفع يروح للي دفع. المعلومات الطبية ليها مسار خاص، للمصرّح لهم بس.')}</div>`;}
function reviewStep(){return `<h2>${T('Everything before you request.','كل التفاصيل قبل الطلب.')}</h2>${rows(true)}<div class="row"><span>${T('Consultation','الكشف')}</span><b>${money(cost())}</b></div><div class="row"><span>${(form.service==='video'?T('Travel','المشوار'):T('Travel in this example','المشوار في المثال'))}</span><b>${(form.service==='video'?T('Not applicable to video','مش مطلوب في الفيديو'):T('Included · no extra fee','ضمن السعر · مفيش رسوم إضافية'))}</b></div><div class="note"><b>${T('Example price, not a published tariff.','سعر تجريبي، مش تسعيرة معتمدة.')}</b>${T('Actual full fees, taxes and inclusions must be agreed before launch. Medicines, tests, nursing and procedures are outside this example.','السعر الفعلي والضرائب والمشمول في الخدمة لازم يتحددوا قبل التشغيل. الأدوية والتحاليل والتمريض والإجراءات برّه المثال ده.')}</div><details><summary>${T('Acceptance, payment and cancellation','القبول والدفع والإلغاء')}</summary><p>${T('This prototype illustrates authorization followed by capture after provider acceptance. This payment design is not verified in the app. A rejected or expired request releases the simulated hold; if real money had already been collected, the supported refund process would apply. Cancellation fees and refund times require agreed terms; no free-cancellation policy is promised.','التجربة بتوضح حجز مبلغ بشكل تجريبي، وبعد قبول الدكتور يتم تحصيله. الطريقة دي لسه مش متحقق من دعمها في التطبيق. لو الطلب اترفض أو انتهت مهلته، الحجز التجريبي للمبلغ بيتفك. لو مبلغ فعلي اتحصّل، لازم يتطبق مسار الاسترداد المعتمد. رسوم الإلغاء ومدة الاسترداد لسه محتاجة اتفاق، ومفيش وعد بإلغاء مجاني.')}</p></details><div class="row"><span>${T('Updates to booker','تحديثات للي بيحجز')}</span><b>${form.who==='self'?T('Your own visit','زيارتك إنت'):form.updates?T('Booking status only · assumed permission','حالة الحجز بس · بإذن مفترض'):T('Payment receipt only','إيصال الدفع بس')}</b></div><label class="check"><input id="ack" type="checkbox" ${form.ack?'checked':''}><span>${T('I understand that this is a simulation using fictional details. No provider is contacted and no money is charged.','فاهم إن دي تجربة ببيانات غير حقيقية. مفيش دكتور هيتم التواصل معاه ومفيش فلوس هتتخصم.')}</span></label>`;}
function statusStep(){const accepted=['accepted','confirmed','complete'].includes(status),confirmed=['confirmed','complete'].includes(status),failed=['declined','expired','cancelled'].includes(status);const titles={pending:T('Request sent. Awaiting acceptance.','الطلب اتبعت. مستني قبول الدكتور.'),accepted:T('Provider accepted. Payment still pending.','الدكتور وافق. الدفع لسه معلّق.'),confirmed:T('The example visit is confirmed.','الزيارة اتأكدت في التجربة.'),declined:T('This request wasn’t accepted.','الطلب ده متقبلش.'),expired:T('The request window ended.','مهلة قبول الطلب انتهت.'),cancelled:T('The example visit was cancelled.','الزيارة التجريبية اتلغت.'),complete:T('The example visit is complete.','الزيارة خلصت في التجربة.')};return `<div class="status-hero ${confirmed?'confirmed-pop':''}">${icon(confirmed?'check':failed?'help':'clock')}<span class="eyebrow">CD-HOME-DEMO · ${T('No real transaction','مفيش معاملة فعلية')}</span><h2>${titles[status]||titles.pending}</h2><p>${T('Use the controls below to explore each service state. Nothing happens automatically in the real world.','جرّب الأزرار تحت علشان تشوف كل حالة. مفيش أي إجراء بيحصل فعلًا.')}</p></div><ol class="timeline"><li class="active"><b>${T('Request and illustrative payment hold','الطلب وحجز مبلغ تجريبي')}</b><small>${failed?T('No charge. Simulated hold released.','مفيش خصم. حجز المبلغ التجريبي اتفك.'):T('No money moved. Authorization is a design example.','مفيش فلوس اتحرّكت. حجز المبلغ تصوّر للتصميم.')}</small></li><li class="${accepted?'active':''}"><b>${T('Professional accepts','المختص يقبل الطلب')}</b><small>${accepted?T('Accepted in this simulation.','تم القبول في التجربة.'):failed?T('No confirmed appointment.','مفيش ميعاد مؤكد.'):T('Still pending. Do not treat this as a confirmed visit.','لسه معلّق. متعتبرش الزيارة مؤكدة.')}</small></li><li class="${confirmed?'active':''}"><b>${T('Payment completes → visit confirmed','الدفع يكتمل ← الزيارة تتأكد')}</b><small>${confirmed?T('Payment and confirmation simulated only.','دفع وتأكيد للتجربة بس.'):T('Acceptance alone is not payment completion.','قبول الطلب لوحده مش معناه إن الدفع اكتمل.')}</small></li></ol>${status==='pending'?`<div class="status-actions">${button(T('Simulate provider acceptance','جرّب قبول الدكتور'),'data-status="accepted"')}${button(T('Try rejection','جرّب الرفض'),'data-status="declined"','')}${button(T('Try no response','جرّب عدم الرد'),'data-status="expired"','')}</div>`:''}${status==='accepted'?`<div class="note warning">${T('Payment is pending. A failed or incomplete payment must not show a confirmed booking.','الدفع لسه معلّق. الدفع اللي مكملش أو فشل مينفعش يظهر كحجز مؤكد.')}</div><div class="status-actions">${button(T('Simulate successful payment','جرّب اكتمال الدفع'),'data-status="confirmed"')}${button(T('Keep payment pending','سيب الدفع معلّق'),'data-modal="pending"','')}</div>`:''}${confirmed?`<div class="note"><b>${T('Before the visit','قبل الزيارة')}</b>${form.service==='home'?T('The recipient would receive provider identity, the address, arrival window and approved preparation. No live tracking or reminder is sent here.','المستفيد يستلم بيانات الدكتور والعنوان وفترة الوصول وتعليمات التجهيز المعتمدة. مفيش تتبّع فعلي أو تذكير بيتبعت هنا.'):T('The recipient would receive private joining instructions and a connection check. No real call, camera or microphone is opened here.','المستفيد يستلم تعليمات دخول خاصة واختبار اتصال. مفيش مكالمة أو كاميرا أو ميكروفون بيتفتحوا هنا.')}<br>${T('Booker updates:','تحديثات اللي بيحجز:')} ${form.who==='self'?T('your own appointment','ميعادك إنت'):form.updates?T('booking status only, under the assumed permission.','حالة الحجز بس، بالإذن المفترض.'):T('payment receipt only; visit coordination stays with the recipient.','إيصال الدفع بس؛ تنسيق الزيارة مع المستفيد.')}</div><div class="status-actions">${status==='confirmed'?button(T('Simulate completion','جرّب اكتمال الزيارة'),'data-status="complete"'):''}${button(T('My care','رعايتي'),'data-go="care"','')}${status==='confirmed'?button(T('Change or cancel','غيّر أو الغي'),'data-modal="manage"',''):''}</div>`:''}${failed?`<div class="note"><b>${T('Choose what happens next.','اختار الخطوة اللي تناسبك.')}</b>${T('No silent replacement. You can review another provider or window. No real charge occurred; actual refunds would follow the approved policy.','مفيش تبديل من غير موافقتك. تقدر تراجع دكتور أو فترة تانية. مفيش خصم فعلي حصل، والاسترداد الحقيقي يتبع السياسة المعتمدة.')}</div>${button(T('Review alternatives','راجع الاختيارات التانية'),'data-retry')}`:''}<div class="mobile-summary">${recipient()} · ${address()}<br>${timeLabel()} · ${money(cost())}</div><div style="margin-top:20px">${button(T('Help with this request','مساعدة في الطلب ده'),'data-modal="support"','text-btn')}</div>`;}
function dock(){const labels=[T('Continue to address','كمّل للعنوان'),T('Choose the service','اختار الخدمة'),T('See example providers','شوف أمثلة الدكاترة'),T('Continue to permissions','كمّل للموافقات'),T('Review the details','راجع التفاصيل'),T('Simulate request','جرّب إرسال الطلب')];const disabled=(step===3&&!availableDays().includes(form.day))||(step===1&&form.area!=='lotus')||(step===4&&!form.agreement)||(step===5&&!form.ack);return `<div class="booking-dock"><div><small>${T('Example only','للتجربة بس')}</small><b>${step>=3?money(cost()):T('Care at their address','الرعاية على عنوان المستفيد')}</b></div><button class="primary" data-next ${disabled?'disabled':''}>${labels[step]}</button></div>`;}
function informational(){const isVideo=page==='video',isHome=page==='home-visits',isHow=page==='how';if(isHow)return `<main id="main" class="dashboard page-enter"><span class="eyebrow">${T('How it works','إزاي بتشتغل')}</span><h1>${T('The details, in the right order.','التفاصيل، بالترتيب الصح.')}</h1><div class="panel">${[T('Choose who receives care.','اختار مين هيستقبل الرعاية.'),T('Set the recipient’s address, not the booker’s location.','حدّد عنوان المستفيد، مش مكان اللي بيحجز.'),T('Review eligible care, provider and usable windows.','راجع الخدمة المناسبة والدكتور وفترات الزيارة.'),T('Confirm recipient agreement and permitted updates.','وضّح موافقة المستفيد والتحديثات المسموح بمشاركتها.'),T('Follow acceptance and payment before confirmation.','تابع القبول والدفع قبل تأكيد الزيارة.'),T('Receive preparation, support and private follow-through.','استلم تعليمات التجهيز والمساعدة والمتابعة بخصوصية.')].map((x,i)=>`<div class="row"><span>0${i+1}</span><b>${x}</b></div>`).join('')}<div class="note">${T('The live product must prove these steps. This prototype demonstrates them using fictional details.','التطبيق الفعلي لازم يثبت إن الخطوات دي بتشتغل. النموذج بيشرحها ببيانات تجريبية.')}</div>${button(T('Try the family flow','جرّب تحجز للعيلة'),'data-start="family"')}</div></main>`;const future={vet:[T('Veterinary care, at home.','رعاية بيطرية في البيت.'),T('A separate future pilot, with species, handling needs, veterinary scope and equipment checks. No veterinary appointments are available here.','تجربة تشغيل لاحقة منفصلة، مع مراجعة نوع الحيوان والتعامل معاه ونطاق الخدمة وتجهيزات الطبيب البيطري. مفيش حجوزات بيطرية متاحة هنا.')],nurse:[T('Nursing with a defined task.','تمريض بمهمة واضحة.'),T('A future, separately reviewed service. Tasks, professional oversight, supplies and aftercare must be defined before bookings are offered.','خدمة لاحقة وليها مراجعة منفصلة. المهام والإشراف والمستلزمات والمتابعة لازم يتحددوا قبل إتاحة الحجز.')],lab:[T('Collection is only one step.','سحب العينة أول خطوة بس.'),T('A future partner pilot needs preparation, sample identification, transport, rejected-sample recovery and private results. No lab is presented as a signed partner.','التجربة مع شريك محتاجة تعليمات تجهيز وتعريف ونقل العينة والتعامل مع رفضها وتسليم النتيجة بخصوصية. مفيش معمل بنقدّمه كشريك متعاقد.')],pharmacy:[T('A pharmacy order needs a pharmacist.','طلب الصيدلية محتاج صيدلي.'),T('Future delivery depends on an accepted pharmacy, prescription review where required, stock, substitutions, delivery and refund rules. No products or medicines are sold here.','التوصيل لاحقًا مرتبط بصيدلية معتمدة ومراجعة الروشتة عند اللزوم والمخزون والبدائل والتوصيل والاسترداد. مفيش بيع منتجات أو أدوية هنا.')]};return `<main id="main" class="dashboard page-enter"><span class="eyebrow">${isHome?T('First proposed pilot · in preparation','أول تجربة تشغيل مقترحة · تحت التجهيز'):isVideo?T('Second priority · preview only','الخطوة التانية · تصوّر فقط'):T('Future service · not bookable','خدمة لاحقة · مش متاحة للحجز')}</span><h1>${isHome?T('A suitable doctor visit.<br>At the address that matters.','زيارة دكتور مناسبة.<br>على العنوان اللي يهمّك.'):isVideo?T('A conversation, when video fits.','استشارة فيديو، لما تكون مناسبة.'):future[page][0]}</h1><div class="panel"><p>${isHome?T('Scheduled, non-emergency adult home consultations in one proposed North Lotus / Fifth Settlement cluster. Actual provider coverage and service windows are still to be accepted.','زيارات منزلية للكبار بميعاد، للحالات غير الطارئة، في نطاق مقترح باللوتس الشمالية والتجمع الخامس. نطاق الدكاترة والمواعيد الفعلية لسه محتاجين اعتماد.'):isVideo?T('A separate release for professionally approved remote care. Recipient identity, physical location in Egypt, consent, secure joining and failed-call recovery must all pass checks.','تشغيل منفصل للرعاية عن بُعد اللي يوافق عليها المختص. لازم نراجع هوية المستفيد ومكانه الفعلي في مصر والموافقة والدخول الآمن والتعامل مع انقطاع الاتصال.'):future[page][1]}</p>${isHome?`<div class="row"><span>${T('Included in the proposed offer','ضمن العرض المقترح')}</span><b>${T('An eligible adult consultation and agreed coordination','كشف مناسب لشخص بالغ وتنسيق متفق عليه')}</b></div><div class="row"><span>${T('Not automatically included','مش ضمن الخدمة تلقائيًا')}</span><b>${T('Medicines, tests, nursing, procedures or emergency care','أدوية أو تحاليل أو تمريض أو إجراءات أو طوارئ')}</b></div>`:''}<div class="note">${T('No actual service, provider capacity or international payment is enabled by this preview.','التصوّر ده مش بيشغّل خدمة أو مواعيد دكاترة أو دفع من برّه مصر.')}</div>${isHome||isVideo?button(T('Explore the demo flow','جرّب الخطوات'),`data-start="family" ${isVideo?'data-start-service="video"':''}`):button(T('Explore the home-first offer','شوف عرض الزيارات المنزلية'),'data-go="home-visits"','')}</div></main>`;}
function providers(){return `<main id="main" class="dashboard page-enter"><span class="eyebrow">CasaBusiness · ${T('Proposed partnership','شراكة مقترحة')}</span><h1>${T('Your time. Your area.<br>A service you can deliver.','وقتك. منطقتك.<br>وخدمة تقدر تقدّمها.')}</h1><p>${T('Start with qualified adult home-doctor care. Other professional and partner categories have separate activation requirements.','البداية بدكاترة مؤهلين للزيارات المنزلية للكبار. باقي التخصصات والشركاء ليهم متطلبات تفعيل منفصلة.')}</p><div class="panel"><div class="mini-journey">${icon('shield')}${icon('pin')}${icon('clock')}${icon('briefcase')}</div>${[[T('01 · Professional scope','٠١ · نطاقك المهني'),T('Credentials, registration and the services you are eligible to deliver.','مؤهلاتك وتسجيلك والخدمات اللي تقدر تقدمها حسب نطاقك المهني.')],[T('02 · Your actual area','٠٢ · منطقتك الفعلية'),T('Travel time, starting point, access and usable coverage.','وقت المشوار ونقطة البداية والدخول والنطاق اللي تقدر تغطيه.')],[T('03 · A workable timetable','٠٣ · جدول قابل للتنفيذ'),T('Service duration, travel buffers and separate home/video availability.','مدة الخدمة ووقت كافي للمشوار، ومواعيد منفصلة للزيارات والفيديو.')],[T('04 · Clear request handling','٠٤ · التعامل مع الطلب بوضوح'),T('Review, accept or decline within the agreed window; know support and escalation contacts.','راجع واقبل أو ارفض خلال المهلة المتفق عليها، واعرف مين يساعدك وإمتى تصعّد المشكلة.')],[T('05 · Agreed commercial terms','٠٥ · شروط تجارية متفق عليها'),T('Signed category/provider terms determine fees, commission, deductions and settlements. No automatic commission-free period or guaranteed earnings.','شروط موقّعة حسب الفئة ومقدم الخدمة بتحدد الرسوم والعمولة والخصومات والتسويات. مفيش فترة إعفاء تلقائية أو دخل مضمون.')]].map(([a,b])=>`<div class="row"><b>${a}</b><span>${b}</span></div>`).join('')}${button(T('Preview the partnership inquiry','شوف استفسار الشراكة'),'data-modal="provider"')}</div><div class="note">${T('This page explains the proposed workflow. It is not a live CasaBusiness dashboard and submits no inquiry.','الصفحة بتشرح مسار الشراكة المقترح، مش لوحة CasaBusiness فعلية ومش بتبعت استفسار.')}</div></main>`;}
function help(){return `<main id="main" class="dashboard page-enter"><span class="eyebrow">${T('Help, with the right team','المساعدة، من الفريق المناسب')}</span><h1>${T('A hand with the next step.','نساعدك في الخطوة الجاية.')}</h1><p>${T('Two separate queues, so a disrupted visit does not get lost among account questions. These are support previews, not connected channels.','مسارين منفصلين، علشان مشكلة في زيارة متضيعش وسط أسئلة الحسابات. دي أمثلة للدعم، مش قنوات متصلة.')}</p><div class="help-grid"><section class="panel">${icon('family')}<h2>${T('Customers & caregivers','العملاء واللي بيرتّبوا الرعاية')}</h2><p>${T('Pending requests, recipient contact, delays, changes and payment/refund follow-up. Medical questions go to a qualified professional.','طلبات معلّقة والتواصل مع المستفيد والتأخير والتغييرات ومتابعة الدفع والاسترداد. الأسئلة الطبية للمختص.')}</p>${button(T('See support routing','شوف مسار المساعدة'),'data-modal="support"')}</section><section class="panel">${icon('briefcase')}<h2>${T('Providers & partners','مقدمو الخدمة والشركاء')}</h2><p>${T('Onboarding, availability, request acceptance, visit access, safety and settlement queries.','التفعيل والمواعيد وقبول الطلب والدخول للزيارة والسلامة وأسئلة التسوية.')}</p>${button(T('Provider help preview','شوف مساعدة مقدمي الخدمة'),'data-modal="provider"')}</section></div><div class="note"><b>${T('Proposed support hours — not a live commitment','ساعات دعم مقترحة — مش التزام بخدمة شغّالة')}</b>${T('Sunday–Thursday, 10:00–18:00 Cairo, subject to an agreed staffed roster. No 24/7 promise. In an emergency, seek local emergency care without waiting for support.','الأحد للخميس، من ١٠ صباحًا لـ٦ مساءً بتوقيت القاهرة، بعد اعتماد فريق فعلي. مفيش وعد بدعم ٢٤ ساعة. في الطوارئ، اطلب رعاية طارئة محلية ومتستناش الدعم.')}</div><h2>${T('Privacy and permission','الخصوصية والموافقات')}</h2><div class="panel"><p>${T('This demo keeps fictional selections in memory only. No clinical details, real names, addresses, phone numbers or payment credentials are requested. Payment receipts, booking coordination and clinical access are separate responsibilities. The live service will need reviewed privacy, consent, cancellation and payment terms before collecting personal data.','التجربة بتحفظ الاختيارات التجريبية في الذاكرة المؤقتة بس. مش بنطلب تفاصيل طبية أو أسماء أو عناوين أو تليفونات حقيقية أو بيانات دفع. إيصالات الدفع وتنسيق الحجز والاطلاع على الملف الطبي مسؤوليات منفصلة. الخدمة الفعلية محتاجة سياسات خصوصية وموافقات وإلغاء ودفع معتمدة قبل جمع بيانات شخصية.')}</p>${faqs()}</div></main>`;}
function care(){return `<main id="main" class="dashboard page-enter"><span class="eyebrow">${T('My care · this session only','رعايتي · خلال الجلسة دي بس')}</span><h1>${T('The details, kept together.','التفاصيل كلها مع بعض.')}</h1>${request?`<section class="panel"><span class="badge">${statusName()}</span><h2 style="margin-top:18px">${serviceName()}</h2>${rows(true)}<div class="note">${T('Your example is kept only while this page stays open. Nothing is stored in an account.','المثال موجود بس طول ما الصفحة مفتوحة. مفيش حاجة بتتحفظ في حساب.')}</div><div class="status-actions">${button(T('View request status','شوف حالة الطلب'),'data-go="book/status"')}${button(T('Support','المساعدة'),'data-modal="support"','')}${['confirmed','pending','accepted'].includes(status)?button(T('Change or cancel','غيّر أو الغي'),'data-modal="manage"',''):''}</div></section>`:`<section class="panel">${icon('heart')}<h2>${T('No example request yet.','لسه مفيش طلب تجريبي.')}</h2><p>${T('Explore the family-booking journey. Your example request and its current status will appear here.','جرّب خطوات الحجز للعيلة. طلبك التجريبي وحالته هيظهروا هنا.')}</p>${button(T('Arrange an example visit','رتّب زيارة تجريبية'),'data-start="family"')}</section>`}</main>`;}
function statusName(){return ({pending:T('Awaiting provider','مستني قبول الدكتور'),accepted:T('Payment pending','الدفع معلّق'),confirmed:T('Confirmed · demo','مؤكد · تجربة'),complete:T('Completed · demo','مكتمل · تجربة'),declined:T('Not accepted','متقبلش'),expired:T('Request expired','مهلة الطلب انتهت'),cancelled:T('Cancelled · demo','ملغي · تجربة')})[status]||T('Draft','مسودة');}
function render(focus=false){document.documentElement.lang=lang==='ar'?'ar-EG':'en';document.documentElement.dir=lang==='ar'?'rtl':'ltr';document.title=T('CasaDoctors · Care that comes to you','كازا دكتورز · الرعاية تيجي لحد عندك');$('#app').innerHTML=head()+(page==='home'?home():page==='book'?booking():page==='providers'?providers():page==='help'?help():page==='care'?care():informational())+footer()+bottom();clearTimeout(appTimer);if(page==='home')appTimer=setTimeout(showAppNudge,18000);if(focus){const h=$('#main h1');if(h){h.tabIndex=-1;h.focus({preventScroll:true});}}}
function go(route){if(location.hash==='#'+route)routeChanged();else location.hash=route;}
function routeChanged(){const route=location.hash.slice(1)||'home';if(route.startsWith('book/')){page='book';step=Math.max(0,steps.indexOf(route.split('/')[1]));if(step===6){if(request)Object.assign(form,request);else step=0;}else if(step>=2&&form.area!=='lotus')step=1;else if(step>=4&&step<6&&!availableDays().includes(form.day))step=3;else if(step===5&&!form.agreement)step=4;if(route!=='book/'+steps[step])history.replaceState(null,'','#book/'+steps[step]);}else{page=['home','home-visits','video','how','providers','help','care','vet','nurse','lab','pharmacy'].includes(route)?route:'home';if(page==='care'&&request)Object.assign(form,request);}render(true);window.scrollTo({top:0,behavior:'instant'});}
function saveStatus(next){status=next;request={...form,status:next};render(true);$('#announce').textContent=statusName();window.scrollTo({top:0,behavior:'instant'});}
function start(who,service='home'){form.day=availableDays()[0];form.area='lotus';form.who=who;form.service=service;form.agreement=false;form.ack=false;status='draft';request=null;go('book/recipient');}
function showAppNudge(){if(page!=='home'||$('#modal').open||document.querySelector('.app-nudge'))return;try{if(sessionStorage.getItem('casa-home-app-nudge'))return;}catch{}const n=document.createElement('aside');n.className='app-nudge';n.setAttribute('aria-label',T('Get the app','نزّل التطبيق'));n.innerHTML=button('×','data-dismiss-app aria-label="'+T('Dismiss app invitation','اقفل دعوة تحميل التطبيق')+'"','modal-close')+'<b>'+T('Keep CasaDoctors close.','خلّي كازا دكتورز قريب منك.')+'</b><p>'+T('Explore the official app.','شوف التطبيق الرسمي.')+'</p>'+button(T('Get the app','نزّل التطبيق'),'data-modal="app"');$('#app').append(n);}
function modal(kind){const d=$('#modal');let content='';if(kind==='app')content=`<h2>${T('Take CasaDoctors with you.','خلّي كازا دكتورز معاك.')}</h2><p>${T('Open the official store listing. The home-first features shown in this concept are not verified in the current app.','افتح صفحة التطبيق الرسمية. مميزات التصوّر المنزلي هنا لسه مش متحقق منها في التطبيق الحالي.')}</p><div class="store-links"><a href="https://play.google.com/store/apps/details?id=com.casadoctors.patient" target="_blank" rel="noopener">Google Play ↗</a><a href="https://apps.apple.com/us/app/casadoctors/id6504245163" target="_blank" rel="noopener">App Store ↗</a></div>`;else if(kind==='manage')content=`<h2>${T('Plans can change.','الترتيبات ممكن تتغيّر.')}</h2><p>${T('A new window needs a new provider review. Cancelling here changes only the demo; actual fees and refund timing depend on approved terms.','الفترة الجديدة محتاجة مراجعة وقبول جديد من الدكتور. الإلغاء هنا بيغيّر التجربة بس؛ الرسوم ومدة الاسترداد الفعلية حسب الشروط المعتمدة.')}</p><div class="status-actions">${button(T('Choose another window','اختار فترة تانية'),'data-reschedule')}${button(T('Simulate cancellation','جرّب الإلغاء'),'data-status="cancelled"','')}</div>`;else if(kind==='pending')content=`<h2>${T('Still pending. Still clear.','لسه معلّق. والحالة واضحة.')}</h2><p>${T('The visit remains unconfirmed. A live service would explain a payment retry or recovery route without charging twice. No card data or charge exists in this demo.','الزيارة لسه مش مؤكدة. الخدمة الفعلية توضّح إعادة محاولة الدفع أو حل المشكلة من غير خصم مرتين. التجربة مفيهاش بيانات كارت أو خصم.')}</p>`;else if(kind==='provider')content=`<h2>${T('A useful partnership conversation.','نبدأ بكلام واضح عن الشراكة.')}</h2><p>${T('The live inquiry would ask for professional category, service area, availability and business contact, then route to Vireal’s provider team. Credential review and signed terms come before activation. This demo sends nothing.','الاستفسار الفعلي يسأل عن فئتك المهنية ومنطقة الخدمة والمواعيد وتواصل الشغل، ويوصل لفريق مقدمي الخدمة في Vireal. مراجعة المؤهلات والشروط الموقّعة قبل التفعيل. التجربة مش بتبعت حاجة.')}</p>`;else content=`<h2>${T('Help for this situation.','مساعدة حسب الموقف.')}</h2><p>${T('For delays or an unaccepted request: operations checks the provider and offers alternatives with permission. For payment or refunds: finance checks the ledger. Clinical or safety concerns go to the qualified escalation owner. A payer receives only information they are authorized to see.','لو فيه تأخير أو طلب متقبلش: التشغيل يراجع مع الدكتور ويعرض بدائل بموافقتك. الدفع والاسترداد: المالية تراجع سجل المعاملات. القلق الطبي أو السلامة للمسؤول المختص. اللي دفع يستلم بس المعلومات المصرّح له يشوفها.')}</p><div class="note">${T('Support preview only. No message is sent. Emergency care must not wait for this channel.','تصوّر للدعم بس. مفيش رسالة بتتبعت. الطوارئ متستناش القناة دي.')}</div>`;d.innerHTML=button('×','data-close aria-label="'+T('Close','اقفل')+'"','modal-close')+content;if(!d.open)d.showModal();}
// Completion module owns routing and user interactions.
